import pandas as pd
import numpy as np
from scipy import stats

# Load all experiments
dfs = {}
for i in range(1, 8):
    try:
        dfs[i] = pd.read_csv(f"experiment_{i}_csv")
        print(f"\n=== Experiment {i} ===")
        print(f"Columns: {list(dfs[i].columns)}")
        print(f"Shape: {dfs[i].shape}")
        print(dfs[i].describe().round(2))
    except Exception as e:
        print(f"Exp {i}: {e}")

# Now look at correlations for experiments that have yield + other vars
print("\n\n=== CORRELATION ANALYSIS ===")
for exp_id, df in dfs.items():
    numeric_cols = df.select_dtypes(include=[np.number]).columns.tolist()
    if len(numeric_cols) >= 2:
        corr_matrix = df[numeric_cols].corr()
        print(f"\n--- Exp {exp_id} correlations ---")
        print(corr_matrix.round(3))

# Look for any experiment with Yield + DefectDensity together
print("\n\n=== YIELD vs DEFECT DENSITY PLOTTING DATA ===")
for exp_id, df in dfs.items():
    if 'WaferYield' in df.columns and 'DefectDensity' in df.columns:
        print(f"\nExp {exp_id}:")
        print(f"  Yield: mean={df['WaferYield'].mean():.2f}, sd={df['WaferYield'].std():.2f}")
        print(f"  DefectDensity: mean={df['DefectDensity'].mean():.2f}, sd={df['DefectDensity'].std():.2f}")
        r = df['WaferYield'].corr(df['DefectDensity'])
        print(f"  Pearson r = {r:.4f}")

# Check all experiments for what was manipulated
print("\n\n=== MANIPULATION SUMMARY ===")
for exp_id, df in dfs.items():
    # Look for action columns
    action_cols = [c for c in df.columns if 'action' in c.lower() or c.lower().startswith('argon') or c.lower().startswith('gas') or c.lower().startswith('clean') or c.lower().startswith('humid')]
    if action_cols:
        print(f"Exp {exp_id} has action cols: {action_cols}")
        for col in action_cols:
            if df[col].nunique() <= 5:
                print(f"  {col}: {df[col].unique()}")
            else:
                print(f"  {col}: mean={df[col].mean():.2f}")
